<script lang="ts">
 import '$lib/styles/canon.css';
 import {onMount,tick} from 'svelte';
 import {focusTrap} from '$lib/actions/a11y.js';
 import Navigation from '$lib/components/Navigation.svelte';
 import Footer from '$lib/components/Footer.svelte';
 import Button from '$lib/components/Button.svelte';
 import TextField from '$lib/components/form/TextField.svelte';
 import Dialog from '$lib/components/feedback/Dialog.svelte';
 import UnifiedSearch from '$lib/navigation/UnifiedSearch.svelte';
 import {DataTable,StatusBadge,type DataTableColumn,type DataTableSortDirection} from '$lib/components/data';
 import PerformancePageSection from '$lib/components/clear/ClearPageSection.svelte';
 import PerformanceDecisionPanel from '$lib/components/clear/ClearDecisionPanel.svelte';
 import PerformanceProofStrip from '$lib/components/clear/ClearProofStrip.svelte';
 import PerformanceReceiptGrid from '$lib/components/clear/ClearReceiptGrid.svelte';
 import PerformanceThesisConditions from '$lib/components/performance/PerformanceThesisConditions.svelte';
 import PerformanceNarrativeStage from '$lib/components/performance/PerformanceNarrativeStage.svelte';
 import PerformanceContrastChapter from '$lib/components/performance/PerformanceContrastChapter.svelte';
 import PerformanceConversionHandoff from '$lib/components/performance/PerformanceConversionHandoff.svelte';
 import PerformanceEvidenceIndex from '$lib/components/performance/PerformanceEvidenceIndex.svelte';
 let dark = $state(true),interactive=$state(false),searchOpen=$state(false),search=$state(''),filter=$state(''),sortKey=$state('title'),direction=$state<DataTableSortDirection>('asc'),selected=$state(''),recordOpen=$state(false);
 let recordsSection:HTMLElement;
 let searchInput:HTMLInputElement|undefined=$state();let previousOpen=false;let searchOpener:HTMLElement|null=null;
 onMount(()=>interactive=true);
 $effect(()=>{if(searchOpen){searchOpener=document.activeElement as HTMLElement;void tick().then(()=>searchInput?.focus());}else if(previousOpen){searchOpener?.focus();}previousOpen=searchOpen;});
 async function chooseSearch(event:MouseEvent,title:string){if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||event.button!==0)return;event.preventDefault();filter=title;searchOpen=false;window.location.hash='records';await tick();recordsSection?.focus();}
 const columns:DataTableColumn[]=[{key:'title',label:'Sample',sortable:true},{key:'owner',label:'Owner',sortable:true},{key:'state',label:'State'},{key:'id',label:'Record',mono:true}];
 const records=[{id:'sample-a',title:'Intake handoff',owner:'Morgan',state:'Draft'},{id:'sample-b',title:'Meeting recap',owner:'Avery',state:'Review'},{id:'sample-c',title:'Project checklist',owner:'Jules',state:'Draft'}];
 const visible=$derived(records.filter(r=>`${r.title} ${r.owner}`.toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>{const key=sortKey as 'title'|'owner';return a[key].localeCompare(b[key])*(direction==='asc'?1:-1);}));
 const searchResults=$derived(records.filter(r=>r.title.toLowerCase().includes(search.toLowerCase())));
 const decisions=[{label:'Prepare',summary:'A bounded draft',title:'Keep the first step small.',detail:'Use the fictional notes to prepare one editable draft.',tone:'allow' as const,evidence:['Fictional source named','Local scope only'],receipts:['sample-scope']},{label:'Review',summary:'Your decision',title:'Stop before sending.',detail:'Check the draft and decide what happens next. No action runs from this example.',tone:'review' as const,evidence:['Owner can edit','Approval remains explicit'],receipts:['sample-review'],actions:[{label:'Inspect a sample',href:'#records'}]},{label:'Stop',summary:'A detail is missing',title:'Keep the draft. Ask one question.',detail:'If the owner or source is missing, retain the work and ask for that detail.',tone:'block' as const,evidence:['No inferred permission'],receipts:['sample-recovery']}];
 const scenes=[{id:'source',label:'Start',summary:'Name the source',title:'A fictional meeting.',detail:'Use the sample notes. No connected account is involved.',tone:'neutral' as const,evidence:['Local sample only']},{id:'review',label:'Review',summary:'Keep the choice visible',title:'A draft is a proposal.',detail:'Read the wording before deciding what happens next.',tone:'review' as const,evidence:['Human review remains explicit']}];
 const evidence=[{id:'sample-scope',kind:'Scope',title:'A fictional intake pilot',detail:'One local draft, no connected accounts.',state:'draft' as const,date:'Sample record',href:'#records'},{id:'sample-review',kind:'Review',title:'A visible stopping point',detail:'The owner reviews the proposed text before anything else.',state:'review' as const,date:'Sample record',href:'#decisions'}];
</script>
<svelte:head><title>Canon · Useful patterns</title><meta name="description" content="Canonical navigation, records, decisions and evidence in one local example."/></svelte:head>
<div class="patterns-page" data-theme={dark?'dark':'light'} data-interactive={interactive}>
 <Navigation logo="Canon" logoHref="/next" showDesktopLogoText showMobileLogoText visualStyle="editorial" links={[{label:'Start here',href:'/next'},{label:'Explore',href:'#records',children:[{label:'Records',href:'#records',description:'Find a draft and inspect its details.'},{label:'Decisions',href:'#decisions',description:'See where human review belongs.'},{label:'Evidence',href:'#evidence',description:'Keep claims and records together.'}]},{label:'Components',href:'/next/components'}]}/>
 <div class="toolbar"><Button variant="secondary" onclick={()=>dark=!dark}>{dark?'Light':'Dark'} appearance</Button><Button onclick={()=>searchOpen=true}>Search samples</Button></div>
 <PerformancePageSection titleLevel="h1" variant="hero" title="Make the work easy to follow." description="A clear beginning, a visible decision, and something useful to hand back. Try these shared Canon patterns with a fictional project.">{#snippet actions()}<Button href="#records">Explore the records</Button><Button variant="secondary" href="#decisions">See the decision path</Button>{/snippet}<p class="scope-note">Local examples only. No account access, provider calls, publishing or live execution.</p></PerformancePageSection>
 <div class="bounded"><PerformanceProofStrip items={[{value:'3 samples',label:'Fictional records to inspect'},{value:'Your decision',label:'A clear review boundary'},{value:'Local only',label:'No external actions'},{value:'Both appearances',label:'The same readable roles'}]}/></div>
 <PerformanceThesisConditions eyebrow="A useful working agreement" title="Clarity before action." description="Keep the work, the boundary and the next step together." conditions={[{label:'Source',title:'Name what you are working from.',detail:'These notes are fictional and stay in this page.'},{label:'Scope',title:'Make the allowed action concrete.',detail:'Prepare a local draft. Do not send or publish it.'},{label:'Review',title:'Leave the next decision with the owner.',detail:'A status badge is not permission to act.',tone:'signal'}]}/>
 <section id="records" bind:this={recordsSection} tabindex="-1" class="bounded records" aria-labelledby="records-title"><h2 id="records-title">A small collection, easy to inspect.</h2><p>Sort by sample or owner. Select a row to inspect its local details.</p><TextField label="Find sample records" bind:value={filter} placeholder="Try Morgan or recap"/><DataTable {columns} rows={visible} {sortKey} sortDirection={direction} caption="Fictional project records" onsort={(key,next)=>{sortKey=key;direction=next;}} onrowclick={(row)=>{selected=row.title;recordOpen=true;}}>{#snippet cell({row,column,value})}{#if column.key==='state'}<StatusBadge label={String(value)} tone={value==='Review'?'warning':'neutral'}/>{:else if column.key==='title'}<span>{value}</span>{:else}{value}{/if}{/snippet}</DataTable></section>
 <div id="decisions"><PerformanceDecisionPanel title="Know when to prepare, review or stop." description="Choose a state. These examples describe a policy; they do not run it." items={decisions} autoRotate={false}/></div>
 <PerformanceEvidenceIndex id="evidence" eyebrow="Keep the context nearby" title="A claim should have somewhere to look." description="These are illustrative records, not receipts from a live run." items={evidence}/>
 <details class="bounded alternative"><summary>Explore a guided explanation and an inverse chapter</summary><PerformanceNarrativeStage id="sample-story" title="One decision at a time." description="A local explanation with a stable link to each scene." {scenes} enablePresentation/><PerformanceContrastChapter density="compact" eyebrow="A useful distinction" title="Prepared is not sent." description="A completed draft does not grant authority to publish." intervention={{label:'A clear boundary',title:'Review comes next.',detail:'Keep the proposed text and the owner’s decision together.'}}/></details>
 <section class="bounded receipts" aria-label="Sample handback"><h2>Something useful to keep.</h2><PerformanceReceiptGrid receipts={[{number:'Scope',label:'What was allowed',detail:'One editable local draft.',href:'#records'},{number:'Review',label:'Who decides next',detail:'The owner reviews the wording.',href:'#decisions'},{number:'Limits',label:'What did not happen',detail:'Nothing was sent or published.',href:'#evidence'},{number:'Recovery',label:'Where to begin again',detail:'Keep the draft and clarify the missing detail.',href:'#decisions'}]}/></section>
 <PerformanceConversionHandoff density="concise" eyebrow="A useful handback" title="Leave the next step clear." description="The work stays local. The owner keeps the decision." handoff={{owner:'Sample owner',authority:'Review before any external action',proof:'Illustrative records above',state:'review'}}>{#snippet actions()}<Button href="#records">Return to the samples</Button>{/snippet}</PerformanceConversionHandoff>
 <Footer mode="ltd" visualStyle="editorial" aboutText="Clear boundaries. Useful progress. This page is a local Canon example." showNewsletter={false} showSocial={false} showRamsQuote={false} quickLinks={[{label:'Guided sample',href:'/next'},{label:'Components',href:'/next/components'},{label:'Back to the records',href:'#records'}]}/>
 <UnifiedSearch bind:open={searchOpen} showMobileButton={false} enableAnalytics={false}>{#snippet content()}<div class="local-search" use:focusTrap={{active:searchOpen}}><h2>Find a sample</h2><label for="sample-search">Search this page’s fictional records</label><input id="sample-search" bind:this={searchInput} bind:value={search} placeholder="Try recap"/><ul>{#each searchResults as item}<li><a href="#records" onclick={(event)=>chooseSearch(event,item.title)}>{item.title}<span>{item.owner}</span></a></li>{/each}</ul>{#if !searchResults.length}<p>No samples match. Try “intake” or clear the search.</p>{/if}<Button variant="secondary" onclick={()=>searchOpen=false}>Close search</Button></div>{/snippet}</UnifiedSearch>
 <Dialog bind:open={recordOpen} title={selected} description="A fictional record, kept local to this example."><p>No external system was read or changed. This draft still needs its owner’s review.</p>{#snippet footer()}<Button onclick={()=>recordOpen=false}>Back to the records</Button>{/snippet}</Dialog>
 <noscript><p class="bounded">The records and decision text are readable without JavaScript. Enable JavaScript to sort, filter and try the local search.</p></noscript>
</div>
<style>
:global(body){margin:0}.patterns-page{font-family:var(--font-performance-sans);background:var(--color-performance-paper);color:var(--color-performance-ink);min-height:100vh}.toolbar{width:min(1180px,calc(100% - 40px));margin:24px auto;display:flex;justify-content:flex-end;gap:12px;flex-wrap:wrap}.bounded{width:min(1180px,calc(100% - 40px));margin:40px auto}.alternative>summary{cursor:pointer;min-height:44px;align-content:center;font-size:18px;margin-bottom:24px}.scope-note{font-size:14px;color:var(--color-performance-muted)}.records h2,.receipts h2{font-size:clamp(26px,3vw,40px);font-weight:500;line-height:1.2}.records :global(.textfield){max-width:480px;margin:28px 0}.records :global(.data-table-scroll){margin-top:24px}.local-search{padding:28px;color:var(--color-performance-ink)}.local-search h2{font-size:28px;font-weight:500}.local-search label{display:block;font-size:15px;margin-bottom:8px}.local-search input{box-sizing:border-box;width:100%;padding:12px;border:1px solid var(--color-performance-border-emphasis);border-radius:12px;color:var(--color-performance-ink);background:var(--color-performance-panel);font:inherit}.local-search ul{list-style:none;padding:0}.local-search a{display:flex;justify-content:space-between;gap:12px;min-height:44px;align-items:center;color:var(--color-performance-ink);padding:12px 0;border-bottom:1px solid var(--color-performance-line)}.local-search a span{color:var(--color-performance-muted);font-size:14px}@media(max-width:600px){.toolbar{justify-content:flex-start}.local-search{padding:20px}}

 .patterns-page { overflow-wrap: anywhere; }

</style>
